class BytesIOCopy:
    """A binary stream, backed by a real OS-level file, that copies
    everything written to it into another stream.

    A real file is used (rather than :class:`io.BytesIO`) so that the
    stream has a valid file descriptor. This allows code under test that
    passes ``sys.stdout``/``sys.stderr`` directly to APIs like
    :func:`subprocess.run` to work under :class:`CliRunner`, instead of
    failing with ``io.UnsupportedOperation: fileno``.

    .. versionadded:: 8.2
    """

    def __init__(self, copy_to: io.BytesIO) -> None:
        self._file = tempfile.TemporaryFile()
        self.copy_to = copy_to

    def __getattr__(self, name: str) -> t.Any:
        return getattr(self._file, name)

    def fileno(self) -> int:
        return self._file.fileno()

    def flush(self) -> None:
        self._file.flush()
        self.copy_to.flush()

    def write(self, b: ReadableBuffer) -> int:
        self.copy_to.write(b)
        return self._file.write(b)

    def getvalue(self) -> bytes:
        pos = self._file.tell()
        self._file.seek(0)
        data = self._file.read()
        self._file.seek(pos)
        return data

